59			return nil, err
60		}
61		if v := find.ID; v != nil {
62			where, args = append(where, "memo.id = "+placeholder(len(args)+1)), append(args, *v)
63		}
64		if len(find.IDList) > 0 {
65			holders := make([]string, 0, len(find.IDList))
66			for _, id := range find.IDList {
67				holders = append(holders, placeholder(len(args)+1))
68				args = append(args, id)
69			}
70			where = append(where, "memo.id IN ("+strings.Join(holders, ", ")+")")
71		}
72		if v := find.UID; v != nil {
73			where, args = append(where, "memo.uid = "+placeholder(len(args)+1)), append(args, *v)
74		}
75		if len(find.UIDList) > 0 {
76			holders := make([]string, 0, len(find.UIDList))
77			for _, uid := range find.UIDList {
78				holders = append(holders, placeholder(len(args)+1))
79				args = append(args, uid)
80			}
81			where = append(where, "memo.uid IN ("+strings.Join(holders, ", ")+")")
82		}
83		if v := find.CreatorID; v != nil {
84			where, args = append(where, "memo.creator_id = "+placeholder(len(args)+1)), append(args, *v)
85		}
86		if v := find.RowStatus; v != nil {
87			where, args = append(where, "memo.row_status = "+placeholder(len(args)+1)), append(args, *v)
88		}
89		if v := find.VisibilityList; len(v) != 0 {
90			holders := []string{}
91			for _, visibility := range v {
92				holders = append(holders, placeholder(len(args)+1))
93				args = append(args, visibility.String())
94			}
95			where = append(where, fmt.Sprintf("memo.visibility in (%s)", strings.Join(holders, ", ")))
96		}
97		if find.ExcludeComments {
98			where = append(where, "memo_relation.related_memo_id IS NULL")
99		}
100	
101		order := "DESC"
102		if find.OrderByTimeAsc {
103			order = "ASC"
104		}
105		orderBy := []string{}
106		if find.OrderByPinned {
107			orderBy = append(orderBy, "pinned DESC")
108		}
109		if find.OrderByUpdatedTs {
110			orderBy = append(orderBy, "updated_ts "+order)
111		} else {
112			orderBy = append(orderBy, "created_ts "+order)
113		}
114		// Add id as final tie-breaker
115		orderBy = append(orderBy, "id DESC")
116		fields := []string{
117			`memo.id AS id`,
118			`memo.uid AS uid`,
119			`memo.creator_id AS creator_id`,
120			`memo.created_ts AS created_ts`,
121			`memo.updated_ts AS updated_ts`,
122			`memo.row_status AS row_status`,
123			`memo.visibility AS visibility`,
124			`memo.pinned AS pinned`,
125			`memo.payload AS payload`,
126			`CASE WHEN parent_memo.uid IS NOT NULL THEN parent_memo.uid ELSE NULL END AS parent_uid`,
127		}
128		if !find.ExcludeContent {
129			fields = append(fields, `memo.content AS content`)
130		}
131	
132		query := `SELECT ` + strings.Join(fields, ", ") + `
133			FROM memo
134			LEFT JOIN "user" AS memo_creator ON memo.creator_id = memo_creator.id
135			LEFT JOIN memo_relation ON memo.id = memo_relation.memo_id AND memo_relation.type = 'COMMENT'
136			LEFT JOIN memo AS parent_memo ON memo_relation.related_memo_id = parent_memo.id
137			WHERE ` + strings.Join(where, " AND ") + `
138			ORDER BY ` + strings.Join(orderBy, ", ")
139		if find.Limit != nil {
140			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
141			if find.Offset != nil {
142				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
143			}
144		}
145	
146		rows, err := d.db.QueryContext(ctx, query, args...)
147		if err != nil {
148			return nil, err
149		}
150		defer rows.Close()
151	
152		list := make([]*store.Memo, 0)
153		for rows.Next() {
154			var memo store.Memo
155			var payloadBytes []byte
156			dests := []any{
157				&memo.ID,
158				&memo.UID,
159				&memo.CreatorID,
160				&memo.CreatedTs,
161				&memo.UpdatedTs,
162				&memo.RowStatus,
163				&memo.Visibility,
164				&memo.Pinned,
165				&payloadBytes,
166				&memo.ParentUID,
167			}
168			if !find.ExcludeContent {
169				dests = append(dests, &memo.Content)
170			}
171			if err := rows.Scan(dests...); err != nil {
172				return nil, err
173			}
174			payload := &storepb.MemoPayload{}
175			if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
176				return nil, errors.Wrap(err, "failed to unmarshal payload")
177			}
178			memo.Payload = payload
179			list = append(list, &memo)
180		}
181	
182		if err := rows.Err(); err != nil {
183			return nil, err
184		}
185	
186		return list, nil
187	}
